package net.civeira.phylax.feature.identity.userfederatedidentity.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.TenantLoginProviderReference;

class LoginProviderVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property login provider of user federated identity ")
  void test_login_provider_v_o_builder() {
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertEquals("10", LoginProviderVO.fromReference("10").getLoginProviderUid(),
        "The builder must store the reference value");
    Assertions.assertEquals("11", LoginProviderVO.tryFromReference("11").getLoginProviderUid(),
        "The builder must store the reference value");
    Assertions.assertEquals("12",
        LoginProviderVO.tryFromReference("12", fails).getLoginProviderUid(),
        "The builder must store the reference value");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertThrows(ConstraintException.class, () -> LoginProviderVO.tryFrom(null));
    Assertions.assertEquals(TenantLoginProviderReference.of("one"),
        LoginProviderVO.from(TenantLoginProviderReference.of("one")).getLoginProvider());
    Assertions.assertThrows(ConstraintException.class,
        () -> LoginProviderVO.tryFrom(new Object() {}));
    Assertions.assertEquals("[" + TenantLoginProviderReference.of("one") + "]",
        LoginProviderVO.from(TenantLoginProviderReference.of("one")).toString());
  }
}
